SELECT * FROM (SELECT CASE WHEN country IN ('UK', 'SG') THEN 'tier_1' ELSE 'other' END country_group, ROUND((100 * SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_us, ROUND(STDDEV(rating), 2) stddev_rating FROM suppliers WHERE country <> 'DE' GROUP BY CASE WHEN country IN ('UK', 'SG') THEN 'tier_1' ELSE 'other' END) agg WHERE pct_us > 60 ORDER BY stddev_rating DESC;
